<?php

namespace App\Models;

use Database\Factories\GeneratedImageFactory;
use Illuminate\Database\Eloquent\Attributes\Scope;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/**
 * A photo generated by the RupaVue booth. The booth writes these rows; the
 * slideshow only reads them.
 *
 * @property int $id
 * @property int $theme_id
 * @property string $generation_status
 * @property string|null $generated_photo_path
 * @property bool $is_deleted
 * @property Carbon|null $created_at
 * @property-read string|null $photo_url
 */
class GeneratedImage extends Model
{
    /** @use HasFactory<GeneratedImageFactory> */
    use HasFactory;

    public const UPDATED_AT = null;

    protected $guarded = ['id'];

    public function getConnectionName(): ?string
    {
        return config('slideshow.connection');
    }

    /**
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'is_deleted' => 'boolean',
        ];
    }

    /**
     * @return BelongsTo<PhotoshootTheme, $this>
     */
    public function theme(): BelongsTo
    {
        return $this->belongsTo(PhotoshootTheme::class, 'theme_id');
    }

    /**
     * Photos that generated successfully, still exist, and have a file.
     *
     * @param  Builder<GeneratedImage>  $query
     */
    #[Scope]
    protected function showable(Builder $query): void
    {
        $query->where('generation_status', 'success')
            ->where('is_deleted', false)
            ->whereNotNull('generated_photo_path');
    }

    /**
     * The booth stores either a full URL or a path on its public disk.
     */
    public function getPhotoUrlAttribute(): ?string
    {
        $path = $this->generated_photo_path;

        if (! $path) {
            return null;
        }

        if (str_starts_with($path, 'http')) {
            return $path;
        }

        return rtrim(config('slideshow.booth_url'), '/').'/storage/'.ltrim($path, '/');
    }
}
